import React, { useEffect } from 'react';
import "./App.css";
import "./css/host.css"
import { useLocation, Link } from 'react-router-dom';
import { ArrowLeftShort } from "react-bootstrap-icons";
function Host() {
    const location = useLocation()

    useEffect(() => {
        if (location.pathname !== "/host") return;
        const starsContainer = document.getElementById("stars");

        if (!starsContainer) return;
        starsContainer.innerHTML = "";

        for (let i = 0; i < 180; i++) {
            const star = document.createElement("div");

            const size =
                Math.random() > 0.96
                    ? "lg"
                    : Math.random() > 0.7
                        ? "md"
                        : "sm";

            star.className = `star ${size}`;

            star.style.left = Math.random() * 100 + "%";
            star.style.top = Math.random() * 100 + "%";

            star.style.animationDuration =
                2 + Math.random() * 6 + "s";

            star.style.animationDelay =
                Math.random() * 5 + "s";

            starsContainer.appendChild(star);
        }
    }, [location.pathname]);

    return (
        <>
            <div className="stars" id="stars"></div>
            <div className="container d-flex flex-column justify-content-center align-items-center p-5 m-5">
                <Link to='/'
                    className="btn back-btn d-flex  align-items-center gap-2 border border-2 text-white rounded-pill"
                >
                    <span> <ArrowLeftShort size={24} /></span>
                    <span className=""> Go Back</span>
                </Link>
            
   <div className=" mt-5">
            <div className="modal-content bg-white rounded-4 shadow p-4">
                 <div className="modal-header border-bottom-0"> 
                    <h1 className="modal-title fs-5">Modal title</h1> 
                    <button type="button" className="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
                     </div> <div className="modal-body py-0"> 
                        <p>This is a modal sheet, a variation of the modal that docs itself to the bottom of the viewport like the newer share sheets in iOS.</p>
                         </div> <div className="modal-footer flex-column align-items-stretch w-100 gap-2 pb-3 border-top-0">
                             <button type="button" className="btn btn-lg btn-primary">Save changes</button>
             <button type="button" className="btn btn-lg btn-secondary" data-bs-dismiss="modal">Close</button>
              </div> 
              </div>
</div>
</div>
        </>
    )
}
export default Host;
